PROGRAM Station

(* SFC Generated from Visual Editor *)

VAR
    (* Step Active Flags *)
    X_step_idle : BOOL := TRUE; (* Step: IDLE *)
    X_step_run : BOOL := FALSE; (* Step: RUN *)
    X_step_seen : BOOL := FALSE; (* Step: SEEN *)
    X_step_full : BOOL := FALSE; (* Step: BATCH_FULL *)
    X_step_fault : BOOL := FALSE; (* Step: JAMMED *)

    (* Step Elapsed Timers *)
    T_step_idle : TON; (* Timer for IDLE *)
    T_step_run : TON; (* Timer for RUN *)
    T_step_seen : TON; (* Timer for SEEN *)
    T_step_full : TON; (* Timer for BATCH_FULL *)
    T_step_fault : TON; (* Timer for JAMMED *)

    (* Previous Step State (P, P0 and P1 pulses) *)
    _XP_step_seen : BOOL := FALSE;
    _XP_step_full : BOOL := FALSE;
    _XP_step_fault : BOOL := FALSE;

    (* Transitions That Fire In This Scan *)
    _F_t_start : BOOL;
    _F_t_stop_run : BOOL;
    _F_t_part : BOOL;
    _F_t_stop_seen : BOOL;
    _F_t_jam : BOOL;
    _F_t_full : BOOL;
    _F_t_next : BOOL;
    _F_t_reset_full : BOOL;
    _F_t_reset_fault : BOOL;
    (* Transition Conditions, as They Were Evaluated In This Scan *)
    _C_t_start : BOOL;
    _C_t_stop_run : BOOL;
    _C_t_part : BOOL;
    _C_t_stop_seen : BOOL;
    _C_t_jam : BOOL;
    _C_t_full : BOOL;
    _C_t_next : BOOL;
    _C_t_reset_full : BOOL;
    _C_t_reset_fault : BOOL;

END_VAR

VAR
    Count : INT := 0; (* Parts counted in this batch *)
END_VAR

VAR_INPUT
    Start AT %I0.0 : BOOL; (* Start pushbutton *)
    Stop AT %I0.1 : BOOL; (* Stop pushbutton *)
    EStop AT %I0.2 : BOOL; (* Emergency stop *)
    Part AT %I0.3 : BOOL; (* Part sensor *)
    Reset AT %I0.4 : BOOL; (* Reset pushbutton *)
END_VAR

VAR_OUTPUT
    Belt AT %Q0.0 : BOOL; (* Belt motor *)
    BatchFull AT %Q0.1 : BOOL; (* Batch full lamp *)
    Fault AT %Q0.2 : BOOL; (* Fault lamp *)
END_VAR

(* === Step Timers === *)
T_step_idle(IN := X_step_idle, PT := T#24h);
T_step_run(IN := X_step_run, PT := T#24h);
T_step_seen(IN := X_step_seen, PT := T#24h);
T_step_full(IN := X_step_full, PT := T#24h);
T_step_fault(IN := X_step_fault, PT := T#24h);

(* === Action Execution === *)
(* Action: A_IDLE *)
IF X_step_idle THEN
    Belt := FALSE; BatchFull := FALSE; Fault := FALSE;
END_IF;

(* Action: A_RUN *)
IF X_step_run OR X_step_seen THEN
    Belt := TRUE; BatchFull := FALSE; Fault := FALSE;
END_IF;

(* Action: A_COUNT *)
IF (X_step_seen AND NOT _XP_step_seen) THEN
    Count := Count + 1;
END_IF;

(* Action: A_FULL *)
IF X_step_full THEN
    Belt := FALSE; BatchFull := TRUE; Fault := FALSE;
END_IF;

(* Action: A_CLEAR *)
IF (NOT X_step_full AND _XP_step_full) OR (NOT X_step_fault AND _XP_step_fault) THEN
    Count := 0;
END_IF;

(* Action: A_FAULT *)
IF X_step_fault THEN
    Belt := FALSE; BatchFull := FALSE; Fault := TRUE;
END_IF;

_XP_step_seen := X_step_seen;
_XP_step_full := X_step_full;
_XP_step_fault := X_step_fault;

(* === Transition Logic === *)
(* Transition: IDLE -> RUN *)
_C_t_start := (Start AND NOT EStop);
_F_t_start := X_step_idle AND _C_t_start;
(* Transition: RUN -> IDLE (Stop or emergency stop) *)
_C_t_stop_run := (Stop OR EStop);
_F_t_stop_run := X_step_run AND _C_t_stop_run;
(* Transition: SEEN -> IDLE (Stop or emergency stop) *)
_C_t_stop_seen := (Stop OR EStop);
_F_t_stop_seen := X_step_seen AND _C_t_stop_seen;
(* Transition: RUN -> SEEN (A part reaches the sensor) *)
_C_t_part := (Part);
_F_t_part := X_step_run AND _C_t_part AND NOT _F_t_stop_run;
(* Transition: SEEN -> JAMMED (The sensor is blocked) *)
_C_t_jam := (T_step_seen.ET >= T#50ms);
_F_t_jam := X_step_seen AND _C_t_jam AND NOT _F_t_stop_seen;
(* Transition: SEEN -> BATCH_FULL (The third part has passed) *)
_C_t_full := (NOT Part AND Count >= 3);
_F_t_full := X_step_seen AND _C_t_full AND NOT _F_t_stop_seen AND NOT _F_t_jam;
(* Transition: SEEN -> RUN (The part has passed) *)
_C_t_next := (NOT Part);
_F_t_next := X_step_seen AND _C_t_next AND NOT _F_t_stop_seen AND NOT _F_t_jam AND NOT _F_t_full;
(* Transition: BATCH_FULL -> IDLE *)
_C_t_reset_full := (Reset);
_F_t_reset_full := X_step_full AND _C_t_reset_full;
(* Transition: JAMMED -> IDLE (Reset works only once the sensor is clear) *)
_C_t_reset_fault := (Reset AND NOT Part);
_F_t_reset_fault := X_step_fault AND _C_t_reset_fault;

IF _F_t_start THEN X_step_idle := FALSE; END_IF;
IF _F_t_stop_run THEN X_step_run := FALSE; END_IF;
IF _F_t_part THEN X_step_run := FALSE; END_IF;
IF _F_t_stop_seen THEN X_step_seen := FALSE; END_IF;
IF _F_t_jam THEN X_step_seen := FALSE; END_IF;
IF _F_t_full THEN X_step_seen := FALSE; END_IF;
IF _F_t_next THEN X_step_seen := FALSE; END_IF;
IF _F_t_reset_full THEN X_step_full := FALSE; END_IF;
IF _F_t_reset_fault THEN X_step_fault := FALSE; END_IF;
IF _F_t_start THEN X_step_run := TRUE; END_IF;
IF _F_t_stop_run THEN X_step_idle := TRUE; END_IF;
IF _F_t_part THEN X_step_seen := TRUE; END_IF;
IF _F_t_stop_seen THEN X_step_idle := TRUE; END_IF;
IF _F_t_jam THEN X_step_fault := TRUE; END_IF;
IF _F_t_full THEN X_step_full := TRUE; END_IF;
IF _F_t_next THEN X_step_run := TRUE; END_IF;
IF _F_t_reset_full THEN X_step_idle := TRUE; END_IF;
IF _F_t_reset_fault THEN X_step_idle := TRUE; END_IF;

END_PROGRAM

